{
  "iteration": 1,
  "summary": "Modular monolith refactor with strict host adapter boundary. Two business domains (FindCare, EvaluateCareQuality) with explicit service classes per UAT feature. HuggingFace reduced to entrypoint + adapter only.",
  "top_level_architecture": {
    "pattern": "Modular Monolith (single process, domain-separated)",
    "layers": [
      "Host Adapter (HuggingFace only)",
      "Application Layer (use cases / orchestration)",
      "Domain Layer (business logic)",
      "Infrastructure Layer (external APIs, DB, embeddings)"
    ],
    "dependency_direction": "Host -> Application -> Domain -> Infrastructure (no upward imports)"
  },
  "huggingface_surface": {
    "allowed_files": [
      "app.py",
      "requirements.txt",
      "static/"
    ],
    "responsibilities": [
      "HTTP routing",
      "request/response translation",
      "stream relay",
      "no business logic"
    ],
    "adapter_class": "HostChatAdapter"
  },
  "proposed_repo_structure": {
    "Code/ConversationalUX/FindCareChat/": {
      "app.py": "HuggingFace entrypoint only",
      "adapter/host_chat_adapter.py": "Translates HTTP <-> Application",
      "application/": {
        "chat_orchestrator.py": "Main orchestrator replacing main.py",
        "tool_router.py": "Safe tool dispatch (replaces globals().get)",
        "session_manager.py": "Chat state + timer"
      },
      "domain/": {
        "find_care/": {
          "provider_search_service.py": "Feature 1",
          "specialty_service.py": "Feature 2",
          "provider_detail_service.py": "Feature 8"
        },
        "evaluate_care_quality/": {
          "clinical_trials_service.py": "Feature 3"
        },
        "shared/": {
          "safety/": {
            "safety_service.py": "Feature 5",
            "emergency_detector.py": "F-09 fix"
          },
          "consent/": {
            "consent_service.py": "Feature 7"
          },
          "lead_capture/": {
            "lead_service.py": "Feature 6"
          },
          "content/": {
            "about_service.py": "Feature 4"
          },
          "unknowns/": {
            "unknown_question_service.py": "Feature 12"
          },
          "url/": {
            "url_guardian.py": "Feature 9 (existing, moved)"
          }
        }
      },
      "infrastructure/": {
        "mongo/": {
          "provider_repository.py": "read-only queries"
        },
        "external_apis/": {
          "npi_client.py",
          "clinical_trials_client.py",
          "google_routes_client.py"
        },
        "embeddings/": {
          "embedding_client.py"
        }
      }
    },
    "Code/DataPipelines/": {
      "no_change": "Acknowledged (F-02 strength)",
      "security_patch": "Add auth to status endpoint (F-06)"
    },
    "Code/Shared/": {
      "logging/": "central logger",
      "config/": "env config loader"
    }
  },
  "tooling_design": {
    "tool_router_class": "ToolRouter",
    "registration_pattern": "explicit dict mapping tool_name -> callable",
    "example": {
      "provider_search": "ProviderSearchService.search()",
      "clinical_trials": "ClinicalTrialsService.search()"
    },
    "fixes": [
      "F-05 eliminate globals().get",
      "F-17 server-side enforcement via router allowlist"
    ]
  },
  "application_layer": {
    "chat_orchestrator_class": "ChatOrchestrator",
    "methods": [
      "handle_user_message(session_id, message)",
      "invoke_tool(tool_name, args)",
      "build_system_prompt()"
    ],
    "responsibilities": [
      "LLM interaction",
      "tool selection loop",
      "safety gating before/after tool calls"
    ]
  },
  "uat_feature_mapping": [
    {
      "feature": "Provider Search",
      "class": "ProviderSearchService",
      "justification": "Core FindCare domain logic"
    },
    {
      "feature": "Specialty Identification",
      "class": "SpecialtyService",
      "justification": "Distinct NLP + taxonomy mapping"
    },
    {
      "feature": "Clinical Trials Search",
      "class": "ClinicalTrialsService",
      "justification": "EvaluateCareQuality domain separation"
    },
    {
      "feature": "About ChatHealthy",
      "class": "AboutService",
      "justification": "Static content but tool-exposed"
    },
    {
      "feature": "Safety Filter",
      "class": "SafetyService",
      "justification": "Cross-cutting, must be centralized"
    },
    {
      "feature": "Lead Capture",
      "class": "LeadService",
      "justification": "Separate consent + storage boundary"
    },
    {
      "feature": "Consent Framework",
      "class": "ConsentService",
      "justification": "Regulatory separation required"
    },
    {
      "feature": "Provider Detail",
      "class": "ProviderDetailService",
      "justification": "Distinct NPI lookup logic"
    },
    {
      "feature": "URL Guardian",
      "class": "URLGuardian",
      "justification": "Already isolated, reused"
    },
    {
      "feature": "Chat UX",
      "class": "SessionManager",
      "justification": "Application-level state, not domain"
    },
    {
      "feature": "Blob Storage Infrastructure",
      "class": "BlobStorageClient",
      "justification": "Infrastructure concern"
    },
    {
      "feature": "Unanswerable Question Handling",
      "class": "UnknownQuestionService",
      "justification": "Distinct fallback pathway"
    },
    {
      "feature": "Markdown Table Rendering",
      "class": "FrontendOnly",
      "justification": "Pure React concern"
    }
  ],
  "security_fixes": {
    "F-05": "ToolRouter allowlist replaces globals dispatch",
    "F-06": "Add API key validation middleware to pipeline status endpoint",
    "F-09": "EmergencyDetector with configurable keyword + embedding similarity",
    "F-17": "All tool access enforced server-side via router",
    "F-16": "Add BrainLockManager with TTL (design only, not implemented)"
  },
  "performance_fixes": {
    "F-10": "Configurable result limit (default 25, adaptive based on query intent)"
  },
  "governance_alignment": {
    "GOV-001": "No provider prioritization logic in services",
    "GOV-002": "Single-tenant config enforced in Config",
    "GOV-004": "LLM suggests, ToolRouter enforces execution",
    "GOV-005": "Strict separation preserved"
  },
  "open_questions": [
    "Should ChatOrchestrator own system prompt or move to PromptBuilder class?",
    "Do we unify FindCare + EvaluateCareQuality under a single facade service?",
    "How strict should tool input validation be (pydantic vs lightweight)?"
  ]
}

{
  "iteration": 2,
  "summary": "Refined modular monolith with explicit facades, corrected domain ownership, full repo coverage, and Pydantic-enforced tool boundaries. Prompt co-location strategy and configurable safety introduced.",
  "top_level_architecture": {
    "pattern": "Modular Monolith (Facade-Oriented Domains)",
    "layers": [
      "Host Adapter (HuggingFace)",
      "Application Layer (Orchestration + Facades)",
      "Domain Layer (Business Services)",
      "Infrastructure Layer (External + DB + Config)"
    ],
    "dependency_direction": "Host -> Application -> Domain -> Infrastructure"
  },
  "repo_refactor_scope": {
    "Code/ConversationalUX/FindCareChat/": {
      "app.py": "HuggingFace entrypoint only",
      "adapter/host_chat_adapter.py": "HTTP <-> ChatOrchestrator",
      "application/": {
        "chat_orchestrator.py": "LLM loop, system prompt (per Boss decision), safety gating",
        "tool_router.py": "Pydantic-validated tool dispatch (allowlist enforced)",
        "session_manager.py": "Chat session + UX state",
        "facades/": {
          "find_care_facade.py": "Entry point for all FindCare capabilities",
          "evaluate_care_facade.py": "Entry point for all EvaluateCareQuality capabilities"
        },
        "tool_models/": {
          "provider_search_models.py": "Pydantic input/output",
          "clinical_trials_models.py": "Pydantic input/output",
          "shared_models.py": "Common tool schemas"
        }
      },
      "domain/": {
        "find_care/": {
          "provider_search_service.py": "Feature 1",
          "specialty_service.py": "Feature 2"
        },
        "evaluate_care_quality/": {
          "clinical_trials_service.py": "Feature 3",
          "provider_detail_service.py": "Feature 8 (MOVED per feedback)"
        },
        "shared/": {
          "safety/": {
            "safety_service.py": "Feature 5",
            "emergency_detector.py": "Config-driven (F-09 fix)"
          },
          "consent/consent_service.py": "Feature 7",
          "lead_capture/lead_service.py": "Feature 6",
          "content/about_service.py": "Feature 4",
          "unknowns/unknown_question_service.py": "Feature 12",
          "url/url_guardian.py": "Feature 9"
        }
      },
      "infrastructure/": {
        "mongo/provider_repository.py": "read-only",
        "external_apis/": {
          "npi_client.py": "used by ProviderDetailService",
          "clinical_trials_client.py": "used by ClinicalTrialsService",
          "google_routes_client.py": "travel time"
        },
        "embeddings/embedding_client.py": "vector search",
        "config/config_loader.py": "loads brain artifacts + env"
      }
    },
    "Code/DataPipelines/": {
      "architecture_alignment": "Remains independent (GOV-005)",
      "changes": [
        "Add APIKeyMiddleware to status endpoint (F-06)",
        "Expose blob schema via Shared contracts if needed"
      ]
    },
    "Code/Shared/": {
      "purpose": "Cross-application infrastructure only (NO business logic)",
      "modules": {
        "logging/logger.py": "central structured logging",
        "config/global_config.py": "shared env loader",
        "contracts/": "optional shared DTOs (non-domain)"
      }
    },
    "Website/": {
      "no_change": "Remains Cloudflare static (GOV-005)",
      "note": "Remove any leaked architecture docs (F-13)"
    },
    "brain/": {
      "machine_artifacts/": {
        "emergency_keywords.json": "loaded by EmergencyDetector",
        "tool_registry.json": "optional future sync for prompt/tool alignment"
      },
      "governance": [
        "Add BrainLock TTL design (F-16 acknowledgment)"
      ]
    }
  },
  "facade_design": {
    "FindCareFacade": {
      "methods": [
        "search_providers(criteria: ProviderSearchInput) -> ProviderSearchOutput",
        "identify_specialty(input: SpecialtyInput) -> SpecialtyOutput",
        "get_provider_location(npi: str) -> dict"
      ]
    },
    "EvaluateCareFacade": {
      "methods": [
        "search_clinical_trials(input: ClinicalTrialsInput) -> ClinicalTrialsOutput",
        "get_provider_details(npi: str) -> ProviderDetailOutput"
      ],
      "cross_calls": [
        "calls FindCareFacade.get_provider_location() for travel calculations"
      ]
    }
  },
  "tooling_and_pydantic": {
    "tool_router": {
      "class": "ToolRouter",
      "dispatch_map": {
        "provider_search": {
          "model": "ProviderSearchInput",
          "handler": "FindCareFacade.search_providers"
        },
        "clinical_trials": {
          "model": "ClinicalTrialsInput",
          "handler": "EvaluateCareFacade.search_clinical_trials"
        }
      },
      "enforcement": [
        "Reject unknown tools (F-05 fix)",
        "Validate all inputs via Pydantic (Boss decision)",
        "Validate outputs before returning to LLM"
      ]
    }
  },
  "system_prompt_strategy": {
    "location": "ChatOrchestrator._build_system_prompt()",
    "strategy": [
      "Prompt references TOOL NAMES only (not class names)",
      "ToolRouter is source of truth for available tools",
      "Optional: load tool descriptions dynamically from tool_models docstrings",
      "Future-ready: tool_registry.json in brain for external sync"
    ],
    "consistency_rule": "If a tool is not registered in ToolRouter, it cannot appear in prompt"
  },
  "uat_feature_mapping": [
    { "feature": "Provider Search", "class": "ProviderSearchService", "domain": "FindCare" },
    { "feature": "Specialty Identification", "class": "SpecialtyService", "domain": "FindCare" },
    { "feature": "Clinical Trials Search", "class": "ClinicalTrialsService", "domain": "EvaluateCareQuality" },
    { "feature": "About ChatHealthy", "class": "AboutService", "domain": "Shared" },
    { "feature": "Safety Filter", "class": "SafetyService", "domain": "Shared" },
    { "feature": "Lead Capture", "class": "LeadService", "domain": "Shared" },
    { "feature": "Consent Framework", "class": "ConsentService", "domain": "Shared" },
    { "feature": "Provider Detail", "class": "ProviderDetailService", "domain": "EvaluateCareQuality" },
    { "feature": "URL Guardian", "class": "URLGuardian", "domain": "Shared" },
    { "feature": "Chat UX", "class": "SessionManager", "domain": "Application" },
    { "feature": "Blob Storage Infrastructure", "class": "BlobStorageClient", "domain": "Infrastructure" },
    { "feature": "Unanswerable Question Handling", "class": "UnknownQuestionService", "domain": "Shared" },
    { "feature": "Markdown Table Rendering", "class": "FrontendOnly", "domain": "Frontend" }
  ],
  "safety_configuration": {
    "EmergencyDetector": {
      "config_source": "brain/machine_artifacts/emergency_keywords.json",
      "reload_strategy": "loaded at startup (no runtime mutation)",
      "future": "can add embedding similarity expansion"
    }
  },
  "audit_alignment": {
    "F-05": "Resolved via ToolRouter allowlist",
    "F-06": "API key protection added to pipelines",
    "F-07": "main.py eliminated -> modular structure",
    "F-09": "Config-driven emergency detection",
    "F-10": "Result limit configurable in ProviderSearchService",
    "F-13": "Website removes sensitive architecture docs",
    "F-16": "BrainLock TTL acknowledged in brain design",
    "F-17": "Server-side enforcement via ToolRouter + Pydantic"
  }
}

{
  "iteration": 3,
  "summary": "Adds phased migration plan, frontend architecture, testing strategy, and final entrypoint definition. Design now fully executable with low-risk incremental refactor.",
  "migration_plan": {
    "strategy": "Strangler Fig pattern inside same codebase (incremental extraction, zero downtime)",
    "phases": [
      {
        "phase": 1,
        "name": "Introduce Skeleton Architecture",
        "changes": [
          "Create folder structure (application/, domain/, infrastructure/, adapter/)",
          "Add ChatOrchestrator (empty pass-through)",
          "Add ToolRouter with static mapping (still calls existing main.py functions)",
          "Wrap existing functions with adapter methods (no logic moved yet)"
        ],
        "result": "App compiles, behavior unchanged, routing no longer uses globals().get",
        "risk": "LOW"
      },
      {
        "phase": 2,
        "name": "Extract First Domain (FindCare - Provider Search)",
        "changes": [
          "Move find_providers() -> ProviderSearchService.search()",
          "Introduce FindCareFacade.search_providers()",
          "Update ToolRouter to call facade instead of main.py"
        ],
        "result": "One feature fully migrated, validates pattern",
        "risk": "LOW"
      },
      {
        "phase": 3,
        "name": "Extract Remaining FindCare सेवices",
        "changes": [
          "Move SpecialtyService",
          "Wire through FindCareFacade",
          "Remove corresponding logic from main.py"
        ],
        "risk": "LOW-MEDIUM"
      },
      {
        "phase": 4,
        "name": "Extract EvaluateCareQuality Domain",
        "changes": [
          "Move ClinicalTrialsService",
          "Move ProviderDetailService",
          "Introduce EvaluateCareFacade"
        ],
        "risk": "MEDIUM"
      },
      {
        "phase": 5,
        "name": "Extract Shared Services",
        "changes": [
          "SafetyService + EmergencyDetector",
          "ConsentService",
          "LeadService",
          "UnknownQuestionService",
          "AboutService",
          "URLGuardian relocation"
        ],
        "risk": "MEDIUM (cross-cutting concerns)"
      },
      {
        "phase": 6,
        "name": "Introduce Pydantic Tool Models",
        "changes": [
          "Define all tool input/output schemas",
          "Wrap ToolRouter validation layer",
          "Gradually enforce typing per tool"
        ],
        "risk": "MEDIUM (schema mismatches)"
      },
      {
        "phase": 7,
        "name": "Delete main.py Monolith",
        "changes": [
          "Remove remaining functions",
          "Ensure all calls go through orchestrator + services",
          "Rename app entrypoint"
        ],
        "risk": "LOW (if prior phases complete)"
      }
    ],
    "safety_mechanism": [
      "Each phase preserves working state",
      "Feature-by-feature migration (no big bang)",
      "Fallback: old functions remain callable until replaced"
    ]
  },
  "frontend_architecture": {
    "location": "Code/ConversationalUX/FindCareChat/frontend/",
    "pattern": "Feature-light, API-driven (no domain duplication)",
    "structure": {
      "src/": {
        "components/": [
          "ChatWindow.tsx",
          "MessageBubble.tsx",
          "EmergencyBanner.tsx",
          "TypingIndicator.tsx"
        ],
        "api/": [
          "chat_client.ts (calls /chat endpoint)"
        ],
        "state/": [
          "chat_store.ts (session state, timer, stop control)"
        ],
        "rendering/": [
          "markdown_renderer.tsx (remark-gfm)"
        ],
        "styles/": [
          "chat.css"
        ]
      }
    },
    "decision": "Do NOT mirror backend domains. Frontend remains thin and presentation-focused. All domain logic stays server-side.",
    "feature_mapping": {
      "Chat UX": "chat_store.ts + ChatWindow.tsx",
      "Markdown Rendering": "markdown_renderer.tsx",
      "Emergency UI": "EmergencyBanner.tsx"
    }
  },
  "testing_strategy": {
    "structure": {
      "tests/": {
        "application/": "test_chat_orchestrator.py",
        "domain/": {
          "find_care/": [
            "test_provider_search_service.py",
            "test_specialty_service.py"
          ],
          "evaluate_care_quality/": [
            "test_clinical_trials_service.py",
            "test_provider_detail_service.py"
          ],
          "shared/": [
            "test_safety_service.py",
            "test_emergency_detector.py",
            "test_consent_service.py",
            "test_lead_service.py",
            "test_unknown_question_service.py"
          ]
        },
        "infrastructure/": [
          "test_provider_repository.py (mocked Mongo)",
          "test_external_clients.py (mock APIs)"
        ]
      }
    },
    "strategy": {
      "unit_tests": "All domain services mocked dependencies",
      "integration_tests": [
        "ToolRouter + Facades",
        "ChatOrchestrator with fake LLM responses"
      ],
      "no_live_calls": "External APIs always mocked in CI",
      "regression": [
        "Capture baseline outputs from main.py before refactor",
        "Replay test prompts and compare outputs"
      ],
      "existing_tests": "Retained initially, then migrated per service"
    }
  },
  "entrypoint_final_state": {
    "main_py": "DELETED",
    "replacement": "app.py",
    "location": "Code/ConversationalUX/FindCareChat/app.py",
    "responsibility": [
      "FastAPI app initialization",
      "Route definitions (/chat, /health, /welcome)",
      "Delegates ALL logic to HostChatAdapter"
    ],
    "adapter": "adapter/host_chat_adapter.py calls ChatOrchestrator",
    "result": "Zero business logic in entrypoint (HuggingFace compliant)"
  },
  "final_notes": [
    "Design now fully incremental and deployable at every phase",
    "Frontend intentionally thin to preserve portability",
    "Testing ensures no regression during phased extraction",
    "main.py fully eliminated to resolve F-07"
  ]
}
